 const current=readFileSync(new URL('../../'+s.file,import.meta.url),'utf8').replaceAll('\r\n','\n');
 assert.equal(hash(current),pin.after,'TELEGRAM_FORMAT_CURRENT_SOURCE_CHANGED');
